<?php
declare(strict_types=1);
require_once __DIR__.'/../config/config.php';header('Content-Type: application/json; charset=utf-8');
if(!current_user()){http_response_code(401);echo json_encode(['ok'=>false,'message'=>'Sign in required.']);exit;}if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit;}verify_csrf();$in=json_decode(file_get_contents('php://input'),true)??[];$ref=trim((string)($in['reference_text']??''));$trans=trim((string)($in['transcript']??''));$lang=preg_replace('/[^a-z0-9-]/i','',(string)($in['language']??'en-US'));if($ref===''){http_response_code(422);echo json_encode(['ok'=>false,'message'=>'Reference text is required.']);exit;}
