// Optional audio assessment adapter contract: POST JSON {audio_base64,mime_type,reference_text,language}; response JSON {score:0..100,feedback:string}. The adapter must be a trusted HTTPS service.
$audio=(string)($in['audio_base64']??'');$assessmentUrl=getenv('LINGUAFREE_SPEECH_ASSESSMENT_URL')?:'';$assessmentKey=getenv('LINGUAFREE_SPEECH_ASSESSMENT_KEY')?:'';
if($audio!==''&&$assessmentUrl!==''&&str_starts_with($assessmentUrl,'https://')&&function_exists('curl_init')){$rawAudio=base64_decode(preg_replace('/^data:[^,]+,/','',$audio),true);if($rawAudio!==false&&strlen($rawAudio)<=5*1024*1024){$payload=['audio_base64'=>base64_encode($rawAudio),'mime_type'=>substr((string)($in['mime_type']??'audio/webm'),0,80),'reference_text'=>$ref,'language'=>$lang];$ch=curl_init($assessmentUrl);curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_RETURNTRANSFER=>true,CURLOPT_HTTPHEADER=>array_filter(['Content-Type: application/json',$assessmentKey?'Authorization: Bearer '.$assessmentKey:null]),CURLOPT_POSTFIELDS=>json_encode($payload),CURLOPT_TIMEOUT=>45]);$raw=curl_exec($ch);$status=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);$out=json_decode((string)$raw,true);if($status>=200&&$status<300&&isset($out['score'])){$score=max(0,min(100,(int)$out['score']));$feedback=substr((string)($out['feedback']??'Audio assessment provided by the configured speech service.'),0,2000);$type='provider_audio';}}}
$st=db()->prepare('INSERT INTO pronunciation_assessments(user_id,language_code,reference_text,transcript,score,assessment_type,feedback) VALUES(?,?,?,?,?,?,?)');$st->execute([current_user()['id'],$lang,$ref,$trans,$score,$type,$feedback]);echo json_encode(['ok'=>true,'score'=>$score,'type'=>$type,'feedback'=>$feedback,'assessment_id'=>(int)db()->lastInsertId()]);
